"""Offline generation tests with literal B2W2 reference levels, no network/SDK."""
from contextlib import redirect_stderr, redirect_stdout
import io
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

from tools import generate_gen5_data as move_generator
from tools.verify_moves.parse_lua import read_moves

from tools.generate_learnsets import GenerationError, collect_learnsets, initial_moves, main, render


# Literal values from pinned PokeAPI VG14, not generated by comparator/oracle.
MOVES = [dict(id=str(identity), identifier=name) for identity, name in [
    (33, 'tackle'), (45, 'growl'), (10, 'scratch'), (39, 'tail-whip'),
    (52, 'ember'), (73, 'leech-seed'), (145, 'bubble'), (100, 'teleport'),
    (150, 'splash'), (175, 'flail'), (77, 'poison-powder'), (79, 'sleep-powder')]]


def event(dex, move_id, level, order=''):
    return dict(pokemon_id=str(dex), move_id=str(move_id), level=str(level), order=str(order),
                version_group_id='14', pokemon_move_method_id='1')


def reference():
    return [event(1, 33, 1), event(1, 45, 3), event(1, 73, 7),
            event(1, 77, 13, 1), event(1, 79, 13, 2),
            event(4, 10, 1, 1), event(4, 45, 1, 2), event(4, 52, 7),
            event(7, 33, 1), event(7, 39, 4), event(7, 145, 7),
            event(63, 100, 1), event(129, 150, 1), event(129, 33, 15), event(129, 175, 30)]


def learnsets(rows=None):
    keys = {'tackle', 'growl', 'scratch', 'tailWhip', 'ember', 'leechSeed', 'bubble',
            'teleport', 'splash', 'flail', 'poisonPowder', 'sleepPowder'}
    return collect_learnsets(MOVES, reference() if rows is None else rows, keys, {1, 4, 7, 63, 129})


class LearnsetGenerationTests(unittest.TestCase):
    def test_known_lv5_starters_match_protected_intro_pairs(self):
        rows = learnsets()
        self.assertEqual(['tackle', 'growl'], initial_moves(rows[1], 5))
        self.assertEqual(['scratch', 'growl'], initial_moves(rows[4], 5))
        self.assertEqual(['tackle', 'tailWhip'], initial_moves(rows[7], 5))

    def test_exact_level_boundary_does_not_grant_future_attack(self):
        rows = learnsets()
        self.assertNotIn('ember', initial_moves(rows[4], 6))
        self.assertIn('ember', initial_moves(rows[4], 7))
        self.assertNotIn('leechSeed', initial_moves(rows[1], 6))
        self.assertIn('bubble', initial_moves(rows[7], 7))

    def test_abra_and_magikarp_sparse_learnsets(self):
        rows = learnsets()
        self.assertEqual(['teleport'], initial_moves(rows[63], 100))
        self.assertEqual(['splash'], initial_moves(rows[129], 14))
        self.assertEqual(['splash', 'tackle'], initial_moves(rows[129], 15))
        self.assertEqual(['splash', 'tackle'], initial_moves(rows[129], 29))
        self.assertEqual(['splash', 'tackle', 'flail'], initial_moves(rows[129], 30))

    def test_explicit_same_level_order_is_not_alphabetized(self):
        rows = learnsets(list(reversed(reference())))
        self.assertEqual(['scratch', 'growl'], initial_moves(rows[4], 1))
        self.assertEqual(['poisonPowder', 'sleepPowder'], [row['move'] for row in rows[1] if row['level'] == 13])

    def test_missing_source_order_has_stable_numeric_id_tie_break(self):
        data = reference() + [event(1, 10, 20), event(1, 33, 20)]
        rows = learnsets(data)
        self.assertEqual(['scratch', 'tackle'], [row['move'] for row in rows[1] if row['level'] == 20])

    def test_existing_duplicate_never_reorders_slots(self):
        events = [dict(move=move, level=level) for move, level in [('a', 1), ('b', 2), ('a', 3), ('c', 4), ('d', 5), ('e', 6)]]
        self.assertEqual(['b', 'c', 'd', 'e'], initial_moves(events, 6))

    def test_forgotten_move_can_reappear_at_later_learning_event(self):
        events = [dict(move=move, level=i + 1) for i, move in enumerate(['a', 'b', 'c', 'd', 'e', 'a'])]
        self.assertEqual(['c', 'd', 'e', 'a'], initial_moves(events, 6))

    def test_level_zero_is_relearn_evolution_only_not_initial(self):
        self.assertEqual(['b'], initial_moves([dict(move='a', level=0), dict(move='b', level=1)], 5))

    def test_repeated_source_events_at_different_levels_are_preserved(self):
        rows = learnsets(reference() + [event(1, 33, 20)])
        self.assertEqual([1, 20], [row['level'] for row in rows[1] if row['move'] == 'tackle'])

    def test_unknown_move_id_fails_not_dropped(self):
        with self.assertRaisesRegex(GenerationError, 'unknown source move ID 999'):
            learnsets(reference() + [event(1, 999, 5)])

    def test_missing_production_moves_fail_with_complete_sorted_list(self):
        with self.assertRaisesRegex(GenerationError, 'missing production moveData definitions: ember, splash'):
            collect_learnsets(MOVES, reference(), {'tackle', 'growl', 'scratch', 'tailWhip', 'leechSeed', 'bubble',
                'teleport', 'flail', 'poisonPowder', 'sleepPowder'}, {1, 4, 7, 63, 129})

    def test_missing_species_and_duplicate_events_fail(self):
        with self.assertRaisesRegex(GenerationError, 'missing source learnsets'):
            collect_learnsets(MOVES, reference(), {'tackle'}, {151})
        with self.assertRaisesRegex(GenerationError, 'duplicate source learn event'):
            learnsets(reference() + [reference()[0].copy()])

    def test_other_versions_and_methods_never_leak_in(self):
        invalid = [dict(event(1, 999, 5), version_group_id='13'),
                   dict(event(1, 999, 5), pokemon_move_method_id='4')]
        self.assertEqual(learnsets(), learnsets(reference() + invalid))

    def test_render_is_idempotent_and_preserves_nonlearnset_content(self):
        source = '''pokemonData = {
    sample = {
        name = "SAMPLE", dex = 4, type = "fire", type2 = nil,
        baseHP = 39, baseAtk = 52, baseDef = 43, baseSpA = 60, baseSpD = 50, baseSpe = 65, baseExp = 62,
        moves = { "wrong" }
    },
}
-- runtime methods and player choices must survive regeneration
function Pokemon:fixture() return "sentinel" end
'''
        roster = {'sample': {'dex': 4}}
        result = render(source, roster, learnsets())
        self.assertEqual(result, render(result, roster, learnsets()))
        self.assertIn('type = "fire", type2 = nil', result)
        self.assertIn('baseHP = 39, baseAtk = 52', result)
        self.assertIn('function Pokemon:fixture() return "sentinel" end', result)
        self.assertIn('move = "ember", level = 7, order = nil, id = 52', result)
        self.assertNotIn('"wrong"', result)

    def test_check_detects_drift_without_writing(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / 'pokemon.lua'; output.write_text('drift')
            with patch('tools.generate_learnsets.generate', return_value=('expected', {})), redirect_stderr(io.StringIO()):
                self.assertEqual(1, main(['--output', str(output), '--check']))
            self.assertEqual('drift', output.read_text())
            output.write_text('expected')
            with patch('tools.generate_learnsets.generate', return_value=('expected', {})), redirect_stdout(io.StringIO()):
                self.assertEqual(0, main(['--output', str(output), '--check']))

    def test_failed_generation_preserves_existing_output(self):
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / 'pokemon.lua'; output.write_text('preserve')
            with patch('tools.generate_learnsets.generate', side_effect=GenerationError('missing production moves')), redirect_stderr(io.StringIO()):
                self.assertEqual(1, main(['--output', str(output)]))
            self.assertEqual('preserve', output.read_text())


class ExtraMoveGeneratorTests(unittest.TestCase):
    def fixture(self):
        def row(identity, identifier, type_id, category, power, accuracy, pp):
            return dict(id=str(identity), identifier=identifier, generation_id='1' if identity < 355 else '5',
                        type_id=str(type_id), damage_class_id=str(category), power=str(power), accuracy=str(accuracy),
                        pp=str(pp), priority='0', target_id='10', effect_chance='')
        charm_meta = dict(move_id='204', meta_ailment_id='0', ailment_chance='0', flinch_chance='0', stat_chance='0',
                          healing='0', drain='0', min_hits='', max_hits='')
        return {'moves': [row(33, 'tackle', 1, 2, 50, 100, 35), row(204, 'charm', 1, 1, 0, 100, 20),
                          row(149, 'psywave', 14, 3, 0, 80, 15), row(480, 'storm-throw', 2, 2, 40, 100, 10)],
                'move_changelog': [], 'move_meta': [charm_meta],
                'move_meta_stat_changes': [dict(move_id='204', stat_id='2', change='-2')],
                'types': [dict(id='1', identifier='normal'), dict(id='14', identifier='psychic'), dict(id='2', identifier='fighting')]}

    def generate(self, directory, data, initial_power=50):
        source, output = Path(directory) / 'input.lua', Path(directory) / 'output.lua'
        source.write_text('moveData = {\n    tackle = Move{ name = "TACKLE", type = "normal", category = "physical", power = '
                          + str(initial_power) + ', accuracy = 100, pp = 35 },\n}\n')
        with patch.object(move_generator, 'MOVES_INPUT', str(source)), patch.object(move_generator, 'MOVES_LUA', str(output)), \
             patch.object(move_generator, 'EXTRA_MOVE_KEYS', ['charm', 'psywave', 'stormThrow']), redirect_stdout(io.StringIO()):
            move_generator.generate_moves(data, preserve_existing=True)
        return output

    def test_three_additions_have_real_payloads_and_preserve_existing_row(self):
        with tempfile.TemporaryDirectory() as directory:
            output = self.generate(directory, self.fixture())
            rows = read_moves(output)
            self.assertEqual(4, len(rows))
            self.assertEqual('normal', rows['charm']['type'])
            self.assertIn('ModifyStat ( DEFENDER , "atk" , -2 )', rows['charm']['effects'][0].text)
            self.assertEqual('PsywaveDamage ( )', rows['psywave']['effects'][0].text)
            self.assertEqual(80, rows['psywave']['accuracy'])
            self.assertEqual(40, rows['stormThrow']['power']); self.assertIs(True, rows['stormThrow']['willCrit'])

    def test_unexpected_existing_payload_change_fails_without_output(self):
        with tempfile.TemporaryDirectory() as directory:
            with self.assertRaisesRegex(ValueError, 'refusing unexpected changes'):
                self.generate(directory, self.fixture(), initial_power=55)
            self.assertFalse((Path(directory) / 'output.lua').exists())

    def test_unknown_or_later_generation_addition_fails_without_partial_output(self):
        for kind in ('unknown', 'later'):
            with self.subTest(kind=kind), tempfile.TemporaryDirectory() as directory:
                data = self.fixture()
                if kind == 'unknown': data['moves'] = data['moves'][:-1]
                else: data['moves'][-1]['generation_id'] = '6'
                with self.assertRaises(ValueError): self.generate(directory, data)
                self.assertFalse((Path(directory) / 'output.lua').exists())


if __name__ == '__main__':
    unittest.main()
